#!/usr/bin/env node
// Generates each agent's native Mission Control role files from the neutral
// role cards in skills/delegate-with-mission-cards/references/roles/.
//
//   node scripts/build_mission_control.mjs          write the generated files
//   node scripts/build_mission_control.mjs --check  fail if any file is stale
//
// Formats follow each agent's official custom-agent documentation (checked 2026-10-25):
// - Codex: ~/.codex/agents/*.toml with name, description, developer_instructions.
//   Codex ignores sandbox_mode in custom agent files (it inherits the parent
//   session), so read-only is carried by the instructions only.
// - Claude Code: ~/.claude/agents/*.md with name, description, tools, model.
// - Gemini CLI: ~/.gemini/agents/*.md with name, description, kind, tools.
// Claude Code and Gemini CLI enforce read-only roles through a tool allowlist.

import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const rolesDir = join(root, "skills", "delegate-with-mission-cards", "references", "roles");
const HEADER = "Generated by scripts/build_mission_control.mjs from skills/delegate-with-mission-cards/references/roles/. Do not edit.";

const READ_ONLY_TOOLS = {
  "claude-code": ["Read", "Grep", "Glob", "WebFetch", "WebSearch"],
  "gemini-cli": ["read_file", "read_many_files", "list_directory", "glob", "grep_search", "google_web_search", "web_fetch"],
};

export const NATIVE_FORMATS = {
  codex: { dir: join("agents", "mission-control"), extension: ".toml", render: renderCodex },
  "claude-code": { dir: join("agents", "claude-code"), extension: ".md", render: renderClaudeCode },
  "gemini-cli": { dir: join("agents", "gemini-cli"), extension: ".md", render: renderGemini },
};

function parseCard(text, file) {
  const match = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(text);
  if (!match) throw new Error(`${file}: expected YAML frontmatter`);
  const fields = Object.fromEntries(
    match[1].split("\n").map((line) => {
      const index = line.indexOf(":");
      return [line.slice(0, index).trim(), line.slice(index + 1).trim()];
    }),
  );
  for (const key of ["name", "description", "access"]) {
    if (!fields[key]) throw new Error(`${file}: missing ${key}`);
  }
  if (!["read-only", "workspace-write"].includes(fields.access)) {
    throw new Error(`${file}: access must be read-only or workspace-write`);
  }
  return { ...fields, body: match[2].trim() };
}

export async function loadRoles() {
  const files = (await readdir(rolesDir)).filter((name) => name.endsWith(".md")).sort();
  return Promise.all(files.map(async (file) => parseCard(await readFile(join(rolesDir, file), "utf8"), file)));
}

// JSON strings are valid TOML basic strings and YAML double-quoted scalars.
const quote = (value) => JSON.stringify(value);

function renderCodex(role) {
  const instructions = role.body.replaceAll("\\", "\\\\").replaceAll('"""', '\\"""');
  return `# ${HEADER}
# Model and reasoning are inherited from the active session.
name = ${quote(role.name)}
description = ${quote(role.description)}
developer_instructions = """
${instructions}
"""
`;
}

function frontmatter(lines) {
  return `---\n# ${HEADER}\n${lines.join("\n")}\n---\n`;
}

function renderClaudeCode(role) {
  const lines = [`name: ${role.name}`, `description: ${quote(role.description)}`];
  if (role.access === "read-only") lines.push(`tools: ${READ_ONLY_TOOLS["claude-code"].join(", ")}`);
  lines.push("model: inherit");
  return `${frontmatter(lines)}\n${role.body}\n`;
}

function renderGemini(role) {
  const lines = [`name: ${role.name}`, `description: ${quote(role.description)}`, "kind: local"];
  if (role.access === "read-only") {
    lines.push("tools:", ...READ_ONLY_TOOLS["gemini-cli"].map((tool) => `  - ${tool}`));
  }
  return `${frontmatter(lines)}\n${role.body}\n`;
}

export async function renderAll() {
  const roles = await loadRoles();
  const files = [];
  for (const format of Object.values(NATIVE_FORMATS)) {
    for (const role of roles) {
      files.push({ path: join(format.dir, role.name + format.extension), content: format.render(role) });
    }
  }
  return files;
}

async function main() {
  const check = process.argv.includes("--check");
  const stale = [];
  for (const file of await renderAll()) {
    const target = join(root, file.path);
    const current = await readFile(target, "utf8").catch(() => null);
    if (current === file.content) continue;
    if (check) {
      stale.push(file.path);
      continue;
    }
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, file.content);
    console.log(`wrote ${file.path}`);
  }
  if (check && stale.length) {
    console.error(`Stale Mission Control files (run node scripts/build_mission_control.mjs):\n  ${stale.join("\n  ")}`);
    process.exit(1);
  }
  if (check) console.log("Mission Control native role files are current.");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) await main();
